{
  "summary": "Renewal request from Acme Cloud Services with a 12% price increase requires checking current contract terms, SLA performance history, and any credits owed before drafting a response with a counter-position.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (pricing, terms, end date, renewal clauses), any SLA policy documents, and recent invoices. Use the SLA credit calculator to determine any SLA misses and credits owed over the contract period. If any amounts are in a foreign currency (e.g., USD), use the currency converter to convert to our reporting currency.",
      "why": "The retriever must gather all contract terms, pricing history, SLA performance, and any credits owed to fully inform a counter-offer or acceptance decision."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the final vendor email response to Acme Cloud Services addressing the renewal request, referencing current contract terms, any SLA credits owed, and a recommended counter-position on the proposed 12% price increase, for human review and approval.",
      "why": "The executor synthesizes the gathered facts into the final reply that a human will review and send."
    }
  ],
  "escalate": null
}
